#pragma once

#include <Arduino.h>

// Proportional bitmap fonts, generated by scripts/generate_fonts.py
struct PixelGlyph
{
  uint16_t codepoint;
  uint8_t width;   // inked columns, at most 8
  uint8_t y;       // first row, counted from the top of the line
  uint8_t height;  // rows stored
  uint16_t offset; // into the font's data, one byte per row, MSB = leftmost pixel
};

struct PixelFont
{
  uint8_t lineHeight;
  uint8_t ascent;
  uint8_t spaceWidth;
  uint16_t glyphCount;
  const PixelGlyph *glyphs; // sorted by codepoint
  const uint8_t *data;
};

extern const PixelFont fontLarge;  // Spleen 8x16, 16 px
extern const PixelFont fontMedium; // X11 6x13, 13 px
extern const PixelFont fontSmall;  // m5x7, 9 px
